function totalOnTime(times: number[], duration: number): number {
  let total = 0;
  let start = times[0], end = times[0] + duration;
  for (let i = 1; i < times.length; i++) {
    const t = times[i];
    if (t < end) {
      end = t + duration; // restarted while on
    } else {
      total += end - start;
      start = t;
      end = t + duration;
    }
  }
  return total + (end - start);
}

