class Solution:
    def totalOnTime(self, times: List[int], duration: int) -> int:
        total = 0
        start, end = times[0], times[0] + duration
        for t in times[1:]:
            if t < end:
                end = t + duration
            else:
                total += end - start
                start, end = t, t + duration
        return total + end - start

