function totalOnTime(times: number[], duration: number): number {
  let total = duration; // the last trigger always runs its full time
  for (let i = 0; i + 1 < times.length; i++) {
    total += Math.min(duration, times[i + 1] - times[i]);
  }
  return total;
}

